import re

# One template for every branch router (Jinja2-style placeholders)
TEMPLATE = """hostname {{ hostname }}
interface GigabitEthernet0/0
 ip address {{ wan_ip }} 255.255.255.252
 ip ospf 1 area {{ area }}
ntp server 10.0.0.10
logging host 10.0.0.20"""

# Per-device variables (in Ansible these would live in YAML files)
branches = [
    {"hostname": "BR1", "wan_ip": "10.255.0.1", "area": 11},
    {"hostname": "BR2", "wan_ip": "10.255.0.5", "area": 11},
]

def render(template, variables):
    # Swap each {{ name }} for that device's value
    return re.sub(r"\{\{\s*(\w+)\s*\}\}", lambda m: str(variables[m.group(1)]), template)

def ensure_line(config, line):
    # Idempotent: add the line only if it is missing
    if line in config.splitlines():
        return config, "ok"
    return config + "\n" + line, "changed"

for device in branches:
    print(render(TEMPLATE, device))
    print("---")

running = render(TEMPLATE, branches[0])
for run in (1, 2):
    running, result = ensure_line(running, "service timestamps log datetime msec")
    print(f"run {run}: {result}")

